81:   command: string,
82: ): { kind: "python"; relOrAbsPath: string } | { kind: "node"; relOrAbsPath: string } | null {
83:   const raw = command.trim();
84:   if (!raw) {
85:     return null;
86:   }
87: 
88:   // Intentionally simple parsing: we only support common forms like
89:   //   python file.py
90:   //   python3 -u file.py
91:   //   node --experimental-something file.js
92:   // If the command is more complex (pipes, heredocs, quoted paths with spaces), skip preflight.
93:   const pythonMatch = raw.match(/^\s*(python3?|python)\s+(?:-[^\s]+\s+)*([^\s]+\.py)\b/i);
94:   if (pythonMatch?.[2]) {
95:     return { kind: "python", relOrAbsPath: pythonMatch[2] };
96:   }

